// Cross-check: the core-wasm build against vectors/core.json (generated by the
// Rust native build of spores-core): every epoch chain (fingerprints, tubes,
// reputation) and every spore state hash.
// Usage: node core-wasm/js/check.mjs   (build first: scripts/build-wasm.sh)
import { existsSync, readFileSync } from 'node:fs';

const root = new URL('../../', import.meta.url);
const vec = JSON.parse(readFileSync(new URL('vectors/core.json', root), 'utf8'));
const path = new URL('target/wasm32-unknown-unknown/wasm/spores_core_wasm.wasm', root);
if (!existsSync(path)) {
  console.log('build first: cargo build --profile wasm -p spores-core-wasm --target wasm32-unknown-unknown (or scripts/build-wasm.sh)');
  process.exit(2);
}
const bytes = readFileSync(path);
const { instance } = await WebAssembly.instantiate(bytes, {});
const x = instance.exports;

/** Calls `fn` (replay or state_hash) with a JSON value; returns the parsed result or throws the wasm's error text. */
function call(fn, value) {
  const input = new TextEncoder().encode(JSON.stringify(value));
  const p = x.alloc(input.length);
  new Uint8Array(x.memory.buffer).set(input, p);
  const code = x[fn](p, input.length);
  x.dealloc(p, input.length);
  const text = new TextDecoder().decode(new Uint8Array(x.memory.buffer, x.result_ptr(), x.result_len()));
  if (code !== 0) throw new Error(text);
  return JSON.parse(text);
}

let bad = 0;
const cmp = (what, got, exp) => {
  const g = JSON.stringify(got), e = JSON.stringify(exp);
  if (g !== e) {
    bad++;
    console.log(`  MISMATCH ${what}\n    got ${g.slice(0, 200)}\n    exp ${e.slice(0, 200)}`);
  }
};

console.log(`core-wasm (${bytes.length} bytes)`);
for (const chain of vec.epoch_chains) {
  const rule = chain.params.pool_rule.rule;
  const input = {
    params: chain.params,
    epochs: chain.epochs.map((e) => ({ epoch: e.epoch, prev_fingerprint: e.prev_fingerprint, active: chain.active, flows: e.payments, rejects: e.rejects, pool: e.pool })),
  };
  const out = call('replay', input);
  cmp(`${rule} chain length`, out.length, chain.epochs.length);
  chain.epochs.forEach((e, i) => {
    cmp(`${rule} epoch ${e.epoch} fingerprint`, out[i]?.fingerprint, e.expect.fingerprint);
    cmp(`${rule} epoch ${e.epoch} prev_fingerprint`, out[i]?.prev_fingerprint, e.prev_fingerprint);
    cmp(`${rule} epoch ${e.epoch} tubes`, out[i]?.tubes, e.expect.conductivity);
    cmp(`${rule} epoch ${e.epoch} reputation`, out[i]?.reputation, e.expect.reputation);
  });
  console.log(`  epoch chain (${rule}): ${chain.epochs.length} epochs`);
}
for (const s of vec.spore_state) {
  const out = call('state_hash', { spore_id: s.id, epoch: s.epoch, seed: s.seed, age: s.age, edges: s.edges });
  cmp(`state ${s.id}@${s.epoch} hash`, out.state_hash, s.state_hash);
  cmp(`state ${s.id}@${s.epoch} canonical`, out.canonical, s.canonical);
}
console.log(`  spore states: ${vec.spore_state.length}`);

// Errors come back as text, not a trap.
try {
  call('replay', { params: vec.params.shipped, epochs: [{ epoch: 1, active: [1], flows: [[1, 9, '5']], rejects: [], pool: '0' }] });
  bad++;
  console.log('  MISMATCH: an inactive spore was accepted');
} catch (e) {
  cmp('error text', e.message, 'epoch 1: spore 9 is not active');
}

console.log(bad === 0 ? 'OK: core-wasm matches the Rust native vectors' : `FAILED: ${bad} mismatches`);
process.exit(bad === 0 ? 0 : 1);
